    >>> from emlearn import cgen
    >>> cgen.struct_init([ 1, 2, 3 ])
    "{ 1, 2, 3 }"
    """
def struct_init(*args: Any) -> object {
    return ('{ ' + ', '.join(str(a) for a in args) + ' }');
}

"""Recursive quicksort"""
def rquicksort(arr: Any) -> object {
    if (len(arr) <= 1) {
        return arr;
    }
    return (
        rquicksort(
            [
                i
                for i in arr[1:]
                if (i < arr[0])
            ]
        )
        + [arr[0]]
        + rquicksort(
            [
                i
                for i in arr[1:]
                if (i > arr[0])
            ]
        )
    );
}
